import json
import itertools

def main():
    # Input variables
    total_days = 14
    cities = ["Amsterdam", "Vienna", "Santorini", "Lyon"]
    desired_days = {
        "Amsterdam": 3,
        "Vienna": 7,
        "Santorini": 4,
        "Lyon": 3,
    }
    # Direct flights (undirected)
    direct_flights = {
        frozenset(["Vienna", "Lyon"]),
        frozenset(["Vienna", "Santorini"]),
        frozenset(["Vienna", "Amsterdam"]),
        frozenset(["Amsterdam", "Santorini"]),
        frozenset(["Lyon", "Amsterdam"]),
    }
    # Must-be-in-city windows (inclusive)
    must_be_windows = {
        # attend workshop in Amsterdam between day 9 and 11 inclusive
        "Amsterdam": (9, 11),
        # attend wedding in Lyon between day 7 and 9 inclusive
        "Lyon": (7, 9),
    }

    # Validate that the sum of desired days matches the rule with overlaps
    n_cities = len(cities)
    sum_desired = sum(desired_days[c] for c in cities)
    if sum_desired != total_days + (n_cities - 1):
        raise ValueError("Desired days do not align with total days given overlap rule.")

    # Check must_be_windows length compatibility with desired durations
    for c, (a, b) in must_be_windows.items():
        if (b - a + 1) > desired_days[c]:
            raise ValueError(f"Window for {c} exceeds its desired days.")

    # Helper to check adjacency flight exists
    def has_direct(a, b):
        return frozenset([a, b]) in direct_flights

    # Compute starts/ends for a given order under overlap rule:
    # s1 = 1, e1 = s1 + L1 - 1
    # si = e(i-1), ei = si + Li - 1
    def compute_schedule(order):
        starts = {}
        ends = {}
        for i, city in enumerate(order):
            L = desired_days[city]
            if i == 0:
                s = 1
            else:
                s = ends[order[i - 1]]
            e = s + L - 1
            starts[city] = s
            ends[city] = e
        return starts, ends

    # Validate schedule for a given order
    def is_valid_order(order):
        # Check direct flights between consecutive cities
        for a, b in zip(order, order[1:]):
            if not has_direct(a, b):
                return False

        starts, ends = compute_schedule(order)

        # Check must-be-in-city windows are contained within the segment
        for c, (a, b) in must_be_windows.items():
            if not (starts[c] <= a <= b <= ends[c]):
                return False

        # Ensure coverage is exactly total_days with overlap rule
        last_end = ends[order[-1]]
        if last_end != total_days:
            return False

        # Ensure the first segment starts on day 1
        if starts[order[0]] != 1:
            return False

        return True

    # Search for a valid itinerary
    valid_order = None
    # Use a deterministic ordering: sort cities for permutation generation
    for order in itertools.permutations(sorted(cities)):
        if is_valid_order(order):
            valid_order = order
            break

    if not valid_order:
        # In case no valid order found (should not happen with given constraints)
        print(json.dumps({"itinerary": []}))
        return

    # Build itinerary output
    starts, ends = compute_schedule(valid_order)
    itinerary = []
    for city in valid_order:
        itinerary.append({
            "day_range": f"Day {starts[city]}-{ends[city]}",
            "place": city
        })

    print(json.dumps({"itinerary": itinerary}, ensure_ascii=False))

if __name__ == "__main__":
    main()
